"""Packages LocalPDF Hub with PyInstaller, from LocalPDF-Hub.spec.

    npm ci && npm run build
    python -m pip install -r requirements-build.txt
    python build.py

Windows: dist/LocalPDF-Hub.exe, one file.
macOS (Apple Silicon): dist/LocalPDF-Hub.app and dist/LocalPDF-Hub-macos-arm64.dmg.
"""

import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
DIST = ROOT / "dist"

# Generated by `npm run build` and kept out of git; without them the UI
# loads with no PDF previews, icons or font.
GENERATED_ASSETS = [
    "libs/pdf.min.mjs",
    "libs/pdf.worker.min.mjs",
    "libs/icons.svg",
    "libs/fonts/ibm-plex-sans-latin-400-normal.woff2",
]


def main() -> None:
    missing = [name for name in GENERATED_ASSETS if not (ROOT / "frontend" / name).is_file()]
    if missing:
        sys.exit(f"frontend/{missing[0]} is missing. Run: npm ci && npm run build")

    command = [sys.executable, "-m", "PyInstaller", "--noconfirm", "--clean", "LocalPDF-Hub.spec"]
    subprocess.run(command, cwd=ROOT, check=True)  # noqa: S603 -- fixed arguments
    if sys.platform == "darwin":
        make_dmg()


def make_dmg() -> None:
    # The disk image shows the app next to a link to Applications, so
    # installing is one drag.
    staging = DIST / "dmg"
    shutil.rmtree(staging, ignore_errors=True)
    staging.mkdir()
    shutil.copytree(DIST / "LocalPDF-Hub.app", staging / "LocalPDF-Hub.app", symlinks=True)
    (staging / "Applications").symlink_to("/Applications")
    dmg = DIST / "LocalPDF-Hub-macos-arm64.dmg"
    command = [
        "hdiutil",
        "create",
        "-volname",
        "LocalPDF Hub",
        "-srcfolder",
        str(staging),
        "-format",
        "UDZO",
        "-ov",
        str(dmg),
    ]
    subprocess.run(command, check=True)  # noqa: S603, S607 -- fixed arguments, system tool
    shutil.rmtree(staging)
    print(dmg.relative_to(ROOT))


if __name__ == "__main__":
    main()
